<?php
require __DIR__.'/includes/bootstrap.php';
$cats=db()->query("SELECT id,name,image FROM categories WHERE is_active=1 ORDER BY sort_order,id")->fetchAll();
$banners=db()->query("SELECT title,subtitle,image_url,link_url FROM banners WHERE is_active=1 ORDER BY sort_order,id")->fetchAll();
$storedStoreName=setting('store_name');$storeName=(!$storedStoreName||$storedStoreName==='الفخامة للشيشة والتبغ')?'معسلات VIP 27':$storedStoreName;$storeDesc=setting('store_description','اكتشف تجربة فاخرة لا مثيل لها');$logo=setting('store_logo');$hero=setting('hero_image');
// Prefer the image saved in Store Settings over the first rotating banner image.
if($hero && !empty($banners)) $banners[0]['image_url']=$hero;
if(!$banners)$banners=[['title'=>$storeName,'subtitle'=>$storeDesc,'image_url'=>$hero?:'https://images.unsplash.com/photo-1524368535928-5b5e00ddc76b?auto=format&fit=crop&w=1800&q=85','link_url'=>'#products']];
$products=db()->query("SELECT id,name,price,image_url,stock FROM products WHERE is_active=1 ORDER BY id DESC LIMIT 24")->fetchAll();
?><!doctype html><html lang="ar" dir="rtl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#080706"><title><?=h($storeName)?></title><link href="https://fonts.googleapis.com/css2?family=Cairo:wght@400;600;700;900&display=swap" rel="stylesheet"><link rel="stylesheet" href="assets/css/store.css?v=55"></head><body><?php include __DIR__.'/includes/nav.php';?><section class="hero"><div class="hero-slides"><?php foreach($banners as $i=>$b):?><article class="hero-slide <?=$i===0?'active':''?>"><img class="hero-art" src="<?=h($b['image_url'])?>" alt="<?=h($b['title'])?>" <?=$i===0?'fetchpriority="high"':'loading="lazy"'?>><div class="hero-shade"></div><div class="hero-text"><small>مرحباً بكم في</small><h1><?=h($b['title'])?></h1><p><?=h($b['subtitle'])?></p><a class="gold" href="<?=h($b['link_url']?:'#products')?>">تسوق الآن　🛒</a></div></article><?php endforeach?></div><div class="dots"></div></section><section id="cats"><h2>✦　تسوّق حسب القسم　✦</h2><div class="carousel"><button id="left" aria-label="الأقسام السابقة">‹</button><div class="track" id="categoryTrack"><button class="cat active" data-id=""><span>✦</span><b>الكل</b></button><?php foreach($cats as $i=>$c):?><button class="cat" data-id="<?=$c['id']?>"><span><?php if($c['image']):?><img src="<?=h($c['image'])?>" alt=""><?php else:?>✧<?php endif?></span><b><?=h($c['name'])?></b></button><?php endforeach?></div><button id="right" aria-label="الأقسام التالية">›</button></div></section><section id="products"><h2 id="productsTitle">✦　أحدث المنتجات　✦</h2><div class="grid" id="productGrid"><?php foreach($products as $p):?><article><a href="product.php?id=<?=$p['id']?>"><img src="<?=h($p['image_url']?:'assets/images/product-placeholder.svg')?>" alt="<?=h($p['name'])?>"><h3><?=h($p['name'])?></h3></a><strong><?=money($p['price'])?></strong><button class="gold add-to-cart" data-id="<?=$p['id']?>" data-name="<?=h($p['name'])?>" data-price="<?=$p['price']?>" data-stock="<?=$p['stock']?>" data-image="<?=h($p['image_url']?:'')?>">أضف إلى السلة</button><a class="details-link" href="product.php?id=<?=$p['id']?>">التفاصيل</a></article><?php endforeach?></div></section><?php include __DIR__.'/includes/footer.php';?><script src="assets/js/store.js?v=55" defer></script></body></html>